cat <<'EOF' > app.py
from flask import Flask, jsonify, request, abort
from dataclasses import dataclass, field
from typing import Dict, List, Any
import itertools

app = Flask(__name__)

state = {
    "store": {
        "name": None,
        "contact_details": None,
        "currency": None,
        "tax_settings": None,
        "shipping_methods": [],
        "payment_options": [],
        "legal_details": None,
        "go_live": False,
    },
    "users": [],
    "products": [],
    "orders": [],
    "cart": [],
}

ids = {"user": itertools.count(1), "product": itertools.count(1), "order": itertools.count(1)}

ROLE_OWNER = "owner"
ROLE_SALES = "sales"
ROLE_CUSTOMER = "customer"

STATUS_PENDING = "pending"
STATUS_BLOCKED = "blocked"
STATUS_ACTIVE = "active"

ORDER_STATUSES = ["new", "paid", "packed", "shipped", "completed", "cancelled"]


def find_user(user_id):
    return next((u for u in state["users"] if u["id"] == user_id), None)


def require_user(user_id, roles=None):
    user = find_user(user_id)
    if not user:
        abort(404, description="User not found")
    if roles and user["role"] not in roles:
        abort(403, description="Forbidden")
    return user


def require_active_customer(user_id):
    user = require_user(user_id, [ROLE_CUSTOMER])
    if user["status"] in {STATUS_PENDING, STATUS_BLOCKED}:
        abort(403, description="Customer account not active")
    return user


def product_by_id(pid):
    return next((p for p in state["products"] if p["id"] == pid), None)


def order_by_id(oid):
    return next((o for o in state["orders"] if o["id"] == oid), None)


def core_settings_complete():
    s = state["store"]
    required = [s["name"], s["contact_details"], s["currency"], s["tax_settings"], s["shipping_methods"], s["payment_options"]]
    return all(required)


@app.get("/health")
def health():
    return {"status": "ok"}


@app.post("/setup")
def setup():
    data = request.get_json(force=True)
    for key in ["name", "contact_details", "currency", "tax_settings", "shipping_methods", "payment_options"]:
        if key not in data:
            abort(400, description=f"Missing {key}")
    state["store"].update({
        "name": data["name"],
        "contact_details": data["contact_details"],
        "currency": data["currency"],
        "tax_settings": data["tax_settings"],
        "shipping_methods": data["shipping_methods"],
        "payment_options": data["payment_options"],
        "legal_details": data.get("legal_details"),
        "go_live": core_settings_complete(),
    })
    return jsonify(state["store"])


@app.post("/users")
def create_user():
    data = request.get_json(force=True)
    role = data.get("role")
    if role not in {ROLE_OWNER, ROLE_SALES, ROLE_CUSTOMER}:
        abort(400, description="Invalid role")
    user = {
        "id": next(ids["user"]),
        "name": data.get("name"),
        "email": data.get("email"),
        "role": role,
        "status": data.get("status", STATUS_ACTIVE if role != ROLE_CUSTOMER else STATUS_PENDING),
    }
    if not user["name"] or not user["email"]:
        abort(400, description="Incomplete user")
    if any(u["email"] == user["email"] for u in state["users"]):
        abort(409, description="Duplicate email")
    state["users"].append(user)
    return jsonify(user), 201


@app.get("/products")
def list_products():
    return jsonify([p for p in state["products"] if p.get("active", True)])


@app.post("/products")
def add_product():
    data = request.get_json(force=True)
    actor = require_user(data.get("actor_id"), [ROLE_OWNER, ROLE_SALES])
    if not data.get("active", True):
        abort(400, description="Products must be active in catalog")
    product = {
        "id": next(ids["product"]),
        "name": data.get("name"),
        "price": data.get("price"),
        "stock": data.get("stock", 0),
        "active": True,
        "low_stock_threshold": data.get("low_stock_threshold", 5),
        "created_by": actor["id"],
    }
    if not product["name"] or product["price"] is None:
        abort(400, description="Incomplete product")
    state["products"].append(product)
    return jsonify(product), 201


@app.post("/cart")
def add_to_cart():
    data = request.get_json(force=True)
    customer = require_active_customer(data.get("customer_id"))
    product = product_by_id(data.get("product_id"))
    qty = int(data.get("quantity", 1))
    if not product or not product.get("active", True):
        abort(404, description="Product not found")
    if qty <= 0 or product["stock"] < qty:
        abort(400, description="Insufficient stock")
    state["cart"].append({"customer_id": customer["id"], "product_id": product["id"], "quantity": qty})
    return jsonify({"cart": state["cart"]})


@app.get("/cart/<int:customer_id>")
def view_cart(customer_id):
    require_active_customer(customer_id)
    return jsonify([c for c in state["cart"] if c["customer_id"] == customer_id])


@app.post("/checkout")
def checkout():
    data = request.get_json(force=True)
    customer = require_active_customer(data.get("customer_id"))
    items = [c for c in state["cart"] if c["customer_id"] == customer["id"]]
    if not items:
        abort(400, description="Empty cart")
    shipping = data.get("shipping_address", {})
    required = ["name", "street_address", "city", "postal_code", "country"]
    if any(not shipping.get(k) for k in required) or not (shipping.get("phone") or shipping.get("email")):
        abort(400, description="Incomplete shipping address")
    total = 0
    order_items = []
    for item in items:
        product = product_by_id(item["product_id"])
        if not product or product["stock"] < item["quantity"]:
            abort(400, description="Item unavailable")
        product["stock"] -= item["quantity"]
        line = product["price"] * item["quantity"]
        total += line
        order_items.append({"product_id": product["id"], "quantity": item["quantity"], "line_total": line})
    order = {
        "id": next(ids["order"]),
        "customer_id": customer["id"],
        "items": order_items,
        "shipping_address": shipping,
        "payment_method": data.get("payment_method", "card"),
        "shipping_method": data.get("shipping_method", "standard"),
        "status": "new",
        "total": total,
    }
    state["orders"].append(order)
    state["cart"] = [c for c in state["cart"] if c["customer_id"] != customer["id"]]
    return jsonify(order), 201


@app.get("/orders/<int:customer_id>")
def orders(customer_id):
    require_active_customer(customer_id)
    return jsonify([o for o in state["orders"] if o["customer_id"] == customer_id])


@app.patch("/orders/<int:order_id>")
def update_order(order_id):
    data = request.get_json(force=True)
    actor = require_user(data.get("actor_id"), [ROLE_OWNER, ROLE_SALES, ROLE_CUSTOMER])
    order = order_by_id(order_id)
    if not order:
        abort(404)
    if actor["role"] == ROLE_CUSTOMER and actor["id"] != order["customer_id"]:
        abort(403)
    if actor["role"] == ROLE_CUSTOMER:
        if data.get("status") != "cancelled" or order["status"] == "shipped":
            abort(403)
        order["status"] = "cancelled"
    else:
        if data.get("status") not in ORDER_STATUSES:
            abort(400)
        if order["status"] in {"shipped", "completed"} and data.get("status") not in {"completed"}:
            abort(403)
        order["status"] = data["status"]
    return jsonify(order)


@app.get("/admin/state")
def admin_state():
    return jsonify(state)


if __name__ == "__main__":
    if not core_settings_complete():
        print("Warning: core store settings incomplete; go-live blocked")
    app.run(host="0.0.0.0", port=8000)
EOF

