import app as webstore


def client():
    webstore.state["store"] = {"name": None, "contact_details": None, "currency": None, "tax_settings": None, "shipping_methods": [], "payment_options": [], "legal_details": None, "go_live": False}
    webstore.state["users"] = []
    webstore.state["products"] = []
    webstore.state["orders"] = []
    webstore.state["cart"] = []
    webstore.ids = {"user": iter(range(1, 1000)), "product": iter(range(1, 1000)), "order": iter(range(1, 1000))}
    webstore.ids = {k: __import__("itertools").count(1) for k in webstore.ids}
    webstore.app.config["TESTING"] = True
    return webstore.app.test_client()


def test_checkout_flow():
    c = client()
    c.post("/setup", json={"name": "Shop", "contact_details": "info@example.com", "currency": "USD", "tax_settings": {"mode": "simple"}, "shipping_methods": ["standard"], "payment_options": ["card"]})
    owner = c.post("/users", json={"name": "Owner", "email": "o@example.com", "role": "owner"}).get_json()
    customer = c.post("/users", json={"name": "Cust", "email": "c@example.com", "role": "customer", "status": "active"}).get_json()
    product = c.post("/products", json={"actor_id": owner["id"], "name": "Widget", "price": 10, "stock": 3, "active": True}).get_json()
    assert c.post("/cart", json={"customer_id": customer["id"], "product_id": product["id"], "quantity": 2}).status_code == 200
    order = c.post("/checkout", json={"customer_id": customer["id"], "shipping_address": {"name": "Cust", "street_address": "1 Main", "city": "Town", "postal_code": "12345", "country": "US", "email": "c@example.com"}, "payment_method": "card", "shipping_method": "standard"}).get_json()
    assert order["status"] == "new"
    assert order["total"] == 20


def test_customer_cannot_edit_other_orders():
    c = client()
    c.post("/setup", json={"name": "Shop", "contact_details": "info@example.com", "currency": "USD", "tax_settings": {"mode": "simple"}, "shipping_methods": ["standard"], "payment_options": ["card"]})
    owner = c.post("/users", json={"name": "Owner", "email": "o@example.com", "role": "owner"}).get_json()
    c1 = c.post("/users", json={"name": "Cust1", "email": "c1@example.com", "role": "customer", "status": "active"}).get_json()
    c2 = c.post("/users", json={"name": "Cust2", "email": "c2@example.com", "role": "customer", "status": "active"}).get_json()
    product = c.post("/products", json={"actor_id": owner["id"], "name": "Widget", "price": 10, "stock": 3, "active": True}).get_json()
    c.post("/cart", json={"customer_id": c1["id"], "product_id": product["id"], "quantity": 1})
    order = c.post("/checkout", json={"customer_id": c1["id"], "shipping_address": {"name": "Cust1", "street_address": "1 Main", "city": "Town", "postal_code": "12345", "country": "US", "phone": "123"}}).get_json()
    r = c.patch(f"/orders/{order['id']}", json={"actor_id": c2["id"], "status": "cancelled"})
    assert r.status_code == 403
EOF

