        abort(400, description="Insufficient stock")
    state["cart"].append({"customer_id": customer["id"], "product_id": product["id"], "quantity": qty})
    return jsonify({"cart": state["cart"]})


@app.get("/cart/<int:customer_id>")
def view_cart(customer_id):
