    return jsonify([c for c in state["cart"] if c["customer_id"] == customer_id])


@app.post("/checkout")
def checkout():
    data = request.get_json(force=True)
    customer = require_active_customer(data.get("customer_id"))
    items = [c for c in state["cart"] if c["customer_id"] == customer["id"]]
    if not items:
        abort(400, description="Empty cart")
    shipping = data.get("shipping_address", {})
    required = ["name", "street_address", "city", "postal_code", "country"]
    if any(not shipping.get(k) for k in required) or not (shipping.get("phone") or shipping.get("email")):
        abort(400, description="Incomplete shipping address")
    total = 0
    order_items = []
    for item in items:
        product = product_by_id(item["product_id"])
        if not product or product["stock"] < item["quantity"]:
            abort(400, description="Item unavailable")
        product["stock"] -= item["quantity"]
        line = product["price"] * item["quantity"]
        total += line
        order_items.append({"product_id": product["id"], "quantity": item["quantity"], "line_total": line})
    order = {
        "id": next(ids["order"]),
        "customer_id": customer["id"],
        "items": order_items,
        "shipping_address": shipping,
        "payment_method": data.get("payment_method", "card"),
        "shipping_method": data.get("shipping_method", "standard"),
        "status": "new",
        "total": total,
    }
    state["orders"].append(order)
    state["cart"] = [c for c in state["cart"] if c["customer_id"] != customer["id"]]
    return jsonify(order), 201


@app.get("/orders/<int:customer_id>")
def orders(customer_id):
    require_active_customer(customer_id)
    return jsonify([o for o in state["orders"] if o["customer_id"] == customer_id])


@app.patch("/orders/<int:order_id>")
def update_order(order_id):
    data = request.get_json(force=True)
    actor = require_user(data.get("actor_id"), [ROLE_OWNER, ROLE_SALES, ROLE_CUSTOMER])
    order = order_by_id(order_id)
    if not order:
        abort(404)
    if actor["role"] == ROLE_CUSTOMER and actor["id"] != order["customer_id"]:
        abort(403)
    if actor["role"] == ROLE_CUSTOMER:
        if data.get("status") != "cancelled" or order["status"] == "shipped":
            abort(403)
        order["status"] = "cancelled"
    else:
        if data.get("status") not in ORDER_STATUSES:
            abort(400)
        if order["status"] in {"shipped", "completed"} and data.get("status") not in {"completed"}:
            abort(403)
        order["status"] = data["status"]
    return jsonify(order)


@app.get("/admin/state")
def admin_state():
    return jsonify(state)


if __name__ == "__main__":
    if not core_settings_complete():
        print("Warning: core store settings incomplete; go-live blocked")
    app.run(host="0.0.0.0", port=8000)
